# Independent holdouts: permutations, canonical Unicode distinctions and iterator storage.
# The native acceptance host supplies the actual candidate module as `module`.
from itertools import permutations
Row = module.CsvRow
for headers in permutations(("first", "second", "first")):
    try:
        Row(headers, ("x", "y", "z"))
    except ValueError:
        pass
    else:
        raise AssertionError("Nonadjacent or reordered exact duplicate admitted")
try:
    Row(iter(("caf\u00e9", "other", "caf\u00e9")), iter(("1", "2", "3")))
except ValueError:
    pass
else:
    raise AssertionError("Duplicate after freezing iterable headers admitted")
for names in (("caf\u00e9", "cafe\u0301"), ("x", "X", " x", "x "), ("",), ()):
    cells = tuple(str(n) for n in range(len(names)))
    row = Row(iter(names), iter(cells))
    assert row.headers == names and row.cells == cells
    assert list(row.as_dict().items()) == list(zip(names, cells))
    assert all(row[name] == row.as_dict()[name] for name in names)
    assert row.convert(lambda r: r.items()) == tuple(zip(names, cells))
    try:
        row.cells = ()
    except (AttributeError, TypeError):
        pass
    else:
        raise AssertionError("Row no longer immutable")
